using System.Security.Cryptography;
using System.Text;
namespace ClinicaEsteticaWeb.Services;
public class SecurityService { private readonly Config _cfg; public SecurityService(IConfiguration c){_cfg=new Config(c);} public string Encrypt(string text){if(text==null)return null; var nonce=RandomNumberGenerator.GetBytes(12);var data=Encoding.UTF8.GetBytes(text);var cipher=new byte[data.Length];var tag=new byte[16];using var aes=new AesGcm(_cfg.Key,16);aes.Encrypt(nonce,data,cipher,tag);var p=new byte[28+cipher.Length];Buffer.BlockCopy(nonce,0,p,0,12);Buffer.BlockCopy(tag,0,p,12,16);Buffer.BlockCopy(cipher,0,p,28,cipher.Length);return Convert.ToBase64String(p);} public string Decrypt(string value){if(string.IsNullOrEmpty(value))return "";var p=Convert.FromBase64String(value);var nonce=p[..12];var tag=p[12..28];var cipher=p[28..];var data=new byte[cipher.Length];using var aes=new AesGcm(_cfg.Key,16);aes.Decrypt(nonce,cipher,tag,data);return Encoding.UTF8.GetString(data);} public string Hmac(string value){using var h=new HMACSHA256(_cfg.Key);return Convert.ToHexString(h.ComputeHash(Encoding.UTF8.GetBytes(value??""))).ToLowerInvariant();} public static string Digits(string s)=>new string((s??"").Where(char.IsDigit).ToArray()); }
